import{_ as h,l as i,o as e,c as r,v as o,p as l,x as n,d as s,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"van Schoot High-NA 光学","description":"","frontmatter":{"title":"van Schoot High-NA 光学","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/vanschoot-high-na-paper.md","filePath":"litho/vanschoot-high-na-paper.md","lastUpdated":1789023840000}'),p={name:"litho/vanschoot-high-na-paper.md"};function A(m,a,d,g,u,S){const t=i("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="van-schoot-high-na-光学" tabindex="-1">van Schoot High-NA 光学 <a class="header-anchor" href="#van-schoot-high-na-光学" aria-label="Permalink to &quot;van Schoot High-NA 光学&quot;">​</a></h1><div class="epigraph"><p>把硅片 NA 从 0.33 抬到约 0.55 时，各向同性 4× 会把掩模侧角度推过多层膜与阴影的墙；变形倍率与半场是光学解，不是把 NXE 光圈拧大一档。</p><footer>—— 对照 van Schoot 等 High-NA 变形光学公开论文，以及主干 asml-high-na 的机台叙述</footer></div><p>附录对照，不插入主干。<a href="/litho/levinson-litho-book">上一课</a>把教材映射到树。本篇对照 Jan van Schoot 等人关于 High-NA EUV 的公开光学论文：为何必须变形（anamorphic）、半场从哪来、与 0.33 全场如何并存。主干 <a href="/litho/asml-high-na">High-NA EXE</a> 已写产品几何；这里只对论文论证，不插入成像课序，也不把论文里的吞吐目标写成实测产能。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 EXE 课已经给出 0.55、约 4×/8×、半场约 26 × 16.5 mm。缺口是文献：这些几何不是产品页先写、论文后补，而是 van Schoot 等在 0.33 量产前就把掩模侧角度、阴影和场尺寸写成约束方程。读论文是为了看见<strong>为什么不能各向同性加倍倍率</strong>，以及半场相对「四分之一场」如何保住扫描经济性。</p><p>论文针对的是光学与系统：多层反射、掩模入射角、工件台加速度。胶随机、出口管制、Chiplet 不在这些篇的主方程里。附录不要把它们读成整厂路线图。</p><h3 id="与产品叶的分工" tabindex="-1">与产品叶的分工 <a class="header-anchor" href="#与产品叶的分工" aria-label="Permalink to &quot;与产品叶的分工&quot;">​</a></h3><p>asml-high-na 写 EXE:5000/5200、Intel 接收等公开里程碑。本篇写 SPIE / JM3 里的成像论证：水平/竖直工艺窗、变形下的 MEF 定义、吸收体选择的模拟。数字以论文当时为准，不把未核实的 wph 抄进课程当事实。</p><p><span class="marginnote">论文讨论过半场相对全场的产能账。那是作者给出的设计目标与模拟，不是本博客测的机台，也不要改写成国产工具吞吐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照两篇公开节点即可，不必列会。van Schoot, van Ingen Schenau, Valentin, Migura, <em>EUV lithography scanner for sub-8 nm resolution</em>, Proc. SPIE 9422, 94221F (2015)：论证 NA 明显高于 0.33 时，4× 下掩模角使阴影毁掉对比，倍率要升到约 8×；若仍用 6 英寸版，各向同性 8× 会把场缩成四分之一，吞吐很难经济；变形扫描系统印半场，并讨论提高光学透过与台加速度以维持经济性。同方向的期刊表述见 van Schoot 等, <em>High-numerical aperture extreme ultraviolet scanner for 8-nm lithography and beyond</em>, J. Micro/Nanolith. MEMS MOEMS 16(4), 041010 (2017)。</p><p>后续 <em>High-NA EUV lithography enabling Moore&#39;s law in the next decade</em>（SPIE，2017）把 NA 0.55、标称约 8 nm、变形镜头与更紧的焦/套刻预算写成下一十年的系统包，并指出 OPC 模型必须为变形光学改写。读法：用主干 EXE 课核对 4×/8× 与半场，用论文核对「为何不是 8× 全向」。论文写于 EXE 出货之前，论证的是光学可行性，不是 2026 年的工厂导入年表。</p>',12)),(e(),l(c,null,{default:n(()=>[E(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E7%A1%85%E7%89%87%20NA%20~%200.55%22%5D%20--%3E%20ANG%5B%22%E6%8E%A9%E6%A8%A1%E4%BE%A7%E8%A7%92%E5%BA%A6%E8%BF%87%E5%A4%A7%22%5D%0A%20%20ANG%20--%3E%20MAG%5B%22%E6%8F%90%E9%AB%98%E5%80%8D%E7%8E%87%E5%8E%8B%E8%A7%92%E5%BA%A6%22%5D%0A%20%20MAG%20--%3E%20AN%5B%22%E5%8F%98%E5%BD%A2%204%C3%97%20%2F%208%C3%97%22%5D%0A%20%20AN%20--%3E%20HF%5B%22%E5%8D%8A%E5%9C%BA%2C%20%E9%9D%9E%E5%9B%9B%E5%88%86%E4%B9%8B%E4%B8%80%E5%9C%BA%22%5D%0A%20%20HF%20--%3E%20EXE%5B%22%E4%B8%BB%E5%B9%B2%20EXE%20%E4%BA%A7%E5%93%81%E5%8F%B6%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="成像对照" tabindex="-1">成像对照 <a class="header-anchor" href="#成像对照" aria-label="Permalink to &quot;成像对照&quot;">​</a></h3><p>van Ingen Schenau 等 <em>Imaging performance of the EUV high NA anamorphic system</em>（SPIE 2015）模拟指出：尽管倍率各向异性，水平与竖直特征的工艺窗可以接近；掩模 CD 误差对竖直与水平的 MEF 要按变形重定义。这解释了主干里「不要写成 EXE 只能做椭圆孔」：硅片侧 NA 仍以 0.55 成像，不对称的是物像倍率。OPC 若仍用各向同性 4× 核，会系统性偏——计算光刻专文已经警告过旧核。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>掩模 NA ≈ 硅片 NA / 倍率。0.55 / 4 把掩模角推过多层布拉格与吸收体阴影的常用窗口；沿最敏感方向升到 8×，角谱拉回。场在狭缝向减半，大芯片拼接，套刻成为新项——论文在系统层已经点到，主干产品课把它写成产线拼接缝。焦深按 \\(\\lambda/\\mathrm{NA}^2\\) 再瘦，随机效应在更小孔上更严，论文承认胶与掩模必须跟上，但不替代 <a href="/litho/euv-stochastics">euv-stochastics</a> 那一课。蔡司侧的公开光学论文（Kneer、Migura、Kaiser 等与 van Schoot 交叉引用）把同一 NA 写成可镀膜、可装校的投影镜组约束；附录读 ASML 系统篇就够对照主干 EXE，不必把镜子张数写进课程。</p><p><span class="marginnote">出处均为 SPIE / JM3 正式文献。不要给 van Schoot 发明 arXiv 编号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇不插入主干，不替代 asml-high-na 的机台合同，不重写蔡司镜子张数。不把论文中的「潜在 &gt;150 wph」一类设计目标写成 2026 年实测，更不写成任何国产机指标。不讨论未公开的 EXE 内部波前。课程序列在图形化检测之后已结束主干；本附录只服务对照。</p><p><span class="marginnote">出处：van Schoot 等 Proc. SPIE 9422, 94221F (2015)；JM3 16(4), 041010 (2017)；High-NA enabling Moore&#39;s law 的 SPIE 续篇。成像补充见 van Ingen Schenau 等变形系统模拟。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 van Schoot 等：High-NA 必须变形与半场，源于掩模侧角度，不是营销改名。</li><li>与主干 asml-high-na 对照：论文写约束方程，产品叶写 EXE 几何与并存。</li><li>各向同性 8× 会缩成四分之一场；变形保住半场。</li><li>不把论文吞吐目标写成实测或国产 wph。</li><li>出处：上列 SPIE / JM3；无虚构预印本。</li></ul>',10))])}const _=h(p,[["render",A]]);export{v as __pageData,_ as default};
